def drive(me, enemy, arena):
    # Simple proportional steering toward the enemy
    try:
        bearing = me.bearing_to(enemy.x, enemy.y)  # degrees, positive = left
    except Exception:
        bearing = 0

    # Base full throttle
    left = 1.0
    right = 1.0

    # Adjust turn: if enemy is to the left, slow right wheel; if to the right, slow left wheel
    if bearing > 5:
        right = 0.4
    elif bearing < -5:
        left = 0.4

    # Clamp to allowed range
    left = max(-1, min(1, left))
    right = max(-1, min(1, right))
    return (left, right)

