def drive(me, enemy, arena):
    # Turn toward the enemy while driving full forward
    try:
        bearing = me.bearing_to(enemy.x, enemy.y)  # degrees, positive = left
    except Exception:
        bearing = 0

    left = 1.0
    right = 1.0

    if bearing > 5:
        right = 0.4
    elif bearing < -5:
        left = 0.4

    left = max(-1, min(1, left))
    right = max(-1, min(1, right))
    return (left, right)


def weapons(me, enemy, arena):
    # Use the front flipper whenever we have shots left
    try:
        fl = me.weapons["front"]
        if fl["type"] == "flipper" and fl.get("shots_left", 0) > 0:
            return [flip("front")]
    except Exception:
        pass
    return None
